function nextPage(rows, afterId, size) {
  if (size <= 0) return [];
  let start = 0;
  if (afterId !== null && afterId !== undefined) {
    let found = -1;
    for (let i = 0; i < rows.length; i += 1) {
      if (rows[i].id === afterId) {
        found = i;
        break;
      }
    }
    if (found === -1) return [];
    start = found + 1;
  }
  const ids = [];
  for (let i = start; i < rows.length && ids.length < size; i += 1) {
    ids.push(rows[i].id);
  }
  return ids;
}

